은 이 (꼬리표 + 1) / 110: 사람 · 로봇마다 바라보는 쪽 (마지막 걸음의 칸 쪽) · 지난 틱에 걸은 칸 수 (걸음보다 먼저 쓰러진 이가 걷던 빠르기 · 쪽으로 떨군다 · 서서 놓은 것은 바라보던 쪽 앞에 — 되살린 세계의 첫 틱도 같게 · PH6b·PH7 검토 고침) / 111: ④ 깨짐 (PH8) — 조각 가면마다 부위 (이음매로 갈린 조각은 그 부위의 층만 — 모양이 바뀌었다) · 바닥 물건의 담긴 물 · 쌓인 맞음 · 찌그러짐 · 칸 가루가 찬다 · 들은 소리에 물체 소리 갈래 셋 (덜그럭 · 쨍그랑 · 드르륵) / 112: ④ 볼트 · 뜯긴 가구 (PH10) — 가구마다 연료 · 열용량이 든 칸 · 문마다 날아간 문짝 (모양이 바뀌었다) · 뜯긴 가구 물체 (Kind 1 — What = 가구) · 문짝 물체 (Kind 3 — What = 문) · 가구 조각 표시 (Flags 8) / 113: 함장의 손 (docs/UI2.md §2) — 기다리는 손 · 한 손 장부 · 차례 (엔진 하나 — 맨 앞) · 원인 갈래 하나 (함장) / 114: 깊이 고침 DF1 — 칸마다 곰팡이가 핀 원인 마디 (생명 끝) · 몸마다 포자를 알린 곰팡이 마디 (몸 끝) / 115: 깊이 고침 DF2 — 사람 · 로봇마다 아는 죽음 (마음) · 누가 처음 안 죽음 (사회 문화 끝) · 이야기 갈래 '좋은 일' / 116: DF1 검토 고침 — 포자를 알린 곰팡이 마디가 몸 끝에서 생명 끝의 (몸 × 곰팡이 마디) 목록으로 (두 얼룩을 오가도 얼룩마다 한 번 — 모양이 바뀌었다) / 117: 깊이 고침 DF3 — 주컴퓨터의 막힌 곳 (문 · 연장선 · 계획 — 까닭 · 번 · 때) · 짐을 줄이려고 끈 장치 · 읽은 탄 연장선 · 사건마다 막힌 곳을 일지에 적었나 · ⑥ 탄 연장선 기록 (끌어온 방 · 받는 방 · 까닭 · 전류) / 118: 깊이 고침 DF4 — 몸마다 잠기운 · 기운 없음 · 잠든 틱 / 119: 깊이 고침 DF8 — 파편이 지난 칸 (칸 · 에너지 · 원인 — ⑥이 읽는다) · 칸마다 지나는 순간 그 칸의 사람이 받아 간 충격 / 120: 깊이 고침 DF9 — 운석이 배의 몸에 넣은 운동량 장부 (N·s 둘 · 각운동량) / 121: DF9 (나) — 벽 · 문 칸마다 피로를 마지막으로 센 부하 (오르내림의 기준) / 122: PH13 정돈 — 쓸어 담은 조각 · 가루 (kg · 조각 수) · 세운 수 / 123: 장 — 마지막으로 구역을 지은 때의 끊긴 칸 (④가 장 뒤에 끊은 틱에 찍어도 되살린 세계가 같은 구역으로)
    public const ulong SaveShape = 0x711c627645c61e6d;

    public byte[] Save()
    {
        var w = new StateWriter(Math.Max(1 << 20, _saveHint));   // 지난 크기만큼 처음부터 (거듭 키우며 옮기지 않게)
        SaveTo(w);
        var bytes = w.ToArray();
        _saveHint = bytes.Length + bytes.Length / 8;
        return bytes;
    }
    private static int _saveHint;

    /// <summary>이 스레드가 계산 일꾼이다 (docs/ENGINE.md §3-10 — 일꾼 안에서는 정적 계측을 쓰지 않는다).</summary>
    [ThreadStatic] public static bool InWorker;

    /// <summary>저장 모양 지문: 값을 빼고 무엇을 어떤 꼴로 쓰는지만 (표준 세계 하나로 잰다 — 배 도면이 바뀌어도 바뀐다: 그 저장은 새 배에 맞지 않으니 판을 올리는 게 맞다).</summary>
    public ulong ShapeOf()
    {
        var w = new StateWriter(1 << 16) { Shape = new() };
        SaveTo(w);
        // 배열 길이를 정하는 종류 수도 (장부 흐름 · 물자 · 사실 · 원인 — 늘면 옛 저장의 배열이 어긋난다)
        w.Shape.Add($"흐름{Book.Flows} 물자{Book.Bulk} 사실{Enum.GetValues<FactKind>().Length} 원인{Enum.GetValues<CauseKind>().Length}");
        return Fingerprint.Of(System.Text.Encoding.UTF8.GetBytes(string.Join("|", w.Shape)));
    }

    private void SaveTo(StateWriter w)
    {
        w.Tag("판");
        w.I32(SaveVersion);
        w.Tag("sim");
        w.I64(Tick);
        Causes.Save(w);
        Facts.Save(w);
        Book.Save(w);
        foreach (var e in _engines) { w.Tag(e.Name); e.Save(w); }
        w.Tag("end");
    }

    public void Load(byte[] data) => Load(new StateReader(data));

    /// <summary>앞 length 바이트만 읽는다 (다시 쓰는 버퍼에 찍어 둔 것 — <see cref="SaveInto"/>).</summary>
    public void Load(byte[] data, int length) => Load(new StateReader(data, length));

    private void Load(StateReader r)
    {
        if (!r.IsTag("판")) throw new InvalidDataException($"판 번호가 없는 저장이다 (판을 붙이기 전에 쓴 것) — 이 엔진은 저장 판 {SaveVersion}만 읽는다");
        int version = r.I32();
        if (version != SaveVersion) throw new InvalidDataException($"저장 판 {version} — 이 엔진은 저장 판 {SaveVersion}만 읽는다");
        r.Tag("sim");
        Tick = r.I64();
        Causes.Load(r);
        Facts.Load(r);
        Book.Load(r);
        foreach (var e in _engines) { r.Tag(e.Name); e.Load(r); }
        r.Tag("end");
        BindAll();
    }

    /// <summary>같은 준비로 새 세계를 만들고 지금 상태를 읽어 넣는다 (주컴퓨터 · 연출의 미래 돌려 보기).</summary>
    public Sim Clone() => Clones(1)[0];

    /// <summary>복제 여럿: 한 번 찍어 모두 읽는다 (찍은 것은 스레드마다 다시 쓰는 버퍼에 — 복제마다 몇 MB를 새로 잡지 않게).</summary>
    public Sim[] Clones(int n)
    {
        var o = new Sim[n];
        for (int i = 0; i < n; i++) o[i] = new Sim(Setup);
        var w = new StateWriter(_cloneBuf ??= new MemoryStream(1 << 20));
        SaveTo(w);
        foreach (var s in o) s.Load(w.Reader());
        return o;
    }
    [ThreadStatic] private static MemoryStream? _cloneBuf;

    /// <summary>
    /// 지금 상태를 buf에 찍고 길이를 돌려준다 — buf가 모자라면 넉넉히 새로 잡는다 (다시보기 고리처럼 같은 칸을 거듭 쓰는 곳: 2분마다 몇 MB를 새로 잡고 버리지 않게).
    /// 바이트는 <see cref="Save"/>와 같다.
    /// </summary>
    public int SaveInto(ref byte[]? buf)
    {
        var w = new StateWriter(_cloneBuf ??= new MemoryStream(1 << 20));
        SaveTo(w);
        int n = w.Length;
        if (buf == null || buf.Length < n) buf = new byte[n + n / 16];
        w.CopyTo(buf);
        return n;
    }

    public ulong Hash() => Fingerprint.Of(Save());
}

/// <summary>세계를 만드는 준비: 배 도면 · 시드 · 켤 엔진.</summary>
public sealed class SimSetup
{
    public Layout Layout { get; }
    public ulong Seed { get; }
    /// <summary>준비가 끝난 세계에 엔진을 붙인다 (시험은 일부만 붙일 수 있다).</summary>
    public Action<Sim> Build { get; }

    public SimSetup(Layout layout, ulong seed, Action<Sim> build)
    {
        Layout = layout; Seed = seed; Build = build;
    }
}
